package com.flightparty.table;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PoolRulesTest {
 @Test void centerCommandsKeepLegacyTrajectory(){assertArrayEquals(new int[]{6062,2465,1,6304,2995,1,6562,2077,1,6784,2744,1,6950,2237,1,6930,2500,1,8475,3641,1,9203,922,1,7150,2379,1,0,0},PoolRules.move(PoolRules.start(),1,234000).cells());}
 @Test void allEightSpotsMatchClientGoldenFixtures(){int[][] cue={{6010,2429},{5965,2974},{5966,3169},{5368,2963},{4989,2500},{5368,2037},{6267,1854},{6080,1928}};for(int spot=1;spot<=8;spot++){int command=spot*363600+234000;var a=PoolRules.move(PoolRules.start(),1,command);var b=PoolRules.move(PoolRules.start(),1,command);assertArrayEquals(a.cells(),b.cells());assertEquals(cue[spot-1][0],a.cells()[0]);assertEquals(cue[spot-1][1],a.cells()[1]);for(int i=0;i<9;i++)if(a.cells()[i*3+2]==1){assertTrue(a.cells()[i*3]>=120&&a.cells()[i*3]<=9880);assertTrue(a.cells()[i*3+1]>=120&&a.cells()[i*3+1]<=4880);}assertTrue(a.history().size()<=49);assertEquals(1,a.moves());}}
 @Test void sideSpinChangesCushionRebound(){var center=PoolRules.move(PoolRules.start(),1,65*3600+1800);var left=PoolRules.move(PoolRules.start(),1,7*363600+65*3600+1800);var right=PoolRules.move(PoolRules.start(),1,3*363600+65*3600+1800);assertNotEquals(center.cells()[1],left.cells()[1]);assertNotEquals(center.cells()[1],right.cells()[1]);assertEquals(0,left.cells()[27]);assertEquals(0,left.cells()[28]);}
 @Test void rejectInvalidSpotCommands(){for(int command:new int[]{-1,0,3599,363600,363600+3599,9*363600+3600,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->PoolRules.move(PoolRules.start(),1,command));}
 @Test void deterministicAndBounded(){var s=PoolRules.start();var a=PoolRules.move(s,1,PoolRules.bot(s));var b=PoolRules.move(s,1,PoolRules.bot(s));assertArrayEquals(a.cells(),b.cells());assertTrue(a.history().size()>1);assertThrows(IllegalArgumentException.class,()->PoolRules.move(s,1,0));}
 @Test void scratchAndBlackRules(){var s=PoolRules.start();s.cells()[0]=400;s.cells()[1]=400;var scratch=PoolRules.move(s,1,50*3600+2250);assertEquals(1,scratch.cells()[2]);assertEquals(2,scratch.turn());for(boolean clear:new boolean[]{false,true}){s=PoolRules.start();if(clear)for(int i=1;i<8;i++)s.cells()[i*3+2]=0;s.cells()[0]=1500;s.cells()[1]=1500;s.cells()[24]=400;s.cells()[25]=400;var result=PoolRules.move(s,1,80*3600+2250);assertTrue(result.over());assertEquals(clear?1:2,result.winner());}}
}
